function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function buildAcceptance(o){
  o=o||{};
  var feature=String(o.feature||'').trim()||'（待填写功能名）';
  var role=String(o.role||'用户').trim()||'用户';
  var caps=splitLines(o.desc);
  if(!caps.length) caps=['核心功能可用'];
  var edges=[
    '输入为空或格式非法时，系统应拦截并提示具体原因',
    '无权限用户尝试操作时，系统应拒绝并引导登录 / 授权',
    '并发或重复提交时，系统应保证幂等、不产生重复数据',
    '依赖服务超时或不可用时，系统应降级并给出友好提示'
  ];
  var nfr=[
    '性能：核心路径 P95 响应时间不超过约定阈值',
    '安全：涉及敏感数据的操作需鉴权与审计日志',
    '兼容：在支持的浏览器 / 设备上行为一致'
  ];
  var lines=[];
  lines.push('# 验收标准：'+feature);
  lines.push('');
  lines.push('- 角色：'+role);
  lines.push('');
  lines.push('## 一、功能验收（Given / When / Then）');
  caps.forEach(function(c,i){
    lines.push('### 场景 '+(i+1)+'：'+c);
    lines.push('- **Given**：作为'+role+'，我已登录并进入相关功能页面');
    lines.push('- **When**：我执行「'+c+'」操作');
    lines.push('- **Then**：系统应正确完成「'+c+'」并给出明确反馈');
    lines.push('');
  });
  lines.push('## 二、边界与异常');
  edges.forEach(function(e){ lines.push('- '+e); });
  lines.push('');
  lines.push('## 三、非功能与约束');
  nfr.forEach(function(n){ lines.push('- '+n); });
  return {title:feature+' 验收标准', scenarioCount:caps.length, edgeCount:edges.length, nfrCount:nfr.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, buildAcceptance:buildAcceptance};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AcceptanceCriteriaForgePure = EXPORTS; }
